import{_ as a,o as t,c as n,a2 as r}from"./chunks/framework.xeBd2WE1.js";const m=JSON.parse('{"title":"AI 动态 · 2026-10-16","description":"","frontmatter":{"title":"AI 动态 · 2026-10-16","date":"2026-10-16T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-10/ai-news-2026-10-16.md","filePath":"news/2026-10/ai-news-2026-10-16.md","lastUpdated":null}'),s={name:"news/2026-10/ai-news-2026-10-16.md"};function o(l,e,i,c,p,d){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-动态-·-2026-10-16" tabindex="-1">AI 动态 · 2026-10-16 <a class="header-anchor" href="#ai-动态-·-2026-10-16" aria-label="Permalink to &quot;AI 动态 · 2026-10-16&quot;">​</a></h1><blockquote><p>截至 2026-10-16。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="meta-联合苹果推出可在-mac-本地运行的开源权重模型" tabindex="-1">Meta 联合苹果推出可在 Mac 本地运行的开源权重模型 <a class="header-anchor" href="#meta-联合苹果推出可在-mac-本地运行的开源权重模型" aria-label="Permalink to &quot;Meta 联合苹果推出可在 Mac 本地运行的开源权重模型&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-10-16">2026-10-16</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/22ecd8733178.webp" alt="配图"></p><p>Meta 发布开源权重模型 Muse Spark Open，与苹果合作可在 Apple silicon 上本地运行，主打编码场景，并已进入 Amazon SageMaker JumpStart。对读者：本地跑编码模型的门槛继续下降，评估时可对比其与云端 API 在成本、隐私和延迟上的取舍。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/10/15/meta-launches-an-open-weight-model-that-runs-on-macs/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="meta-新条款或允许免费抓取新闻站点训练-ai" tabindex="-1">Meta 新条款或允许免费抓取新闻站点训练 AI <a class="header-anchor" href="#meta-新条款或允许免费抓取新闻站点训练-ai" aria-label="Permalink to &quot;Meta 新条款或允许免费抓取新闻站点训练 AI&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-10-16">2026-10-16</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/d34393f8d1ac.jpg" alt="配图"></p><p>据 Nieman Lab 报道，Meta 将于 10 月 30 日生效的新商业条款，可能授权其抓取使用其平台的企业「关联」网站内容用于训练 AI，法律专家认为这可能让 Meta 主张商业条款优先于 robots 等屏蔽指令。对读者：内容与媒体类站点应尽快核查条款适用范围，必要时调整屏蔽与授权策略。</p><p class="news-entry-source"><a href="https://www.theverge.com/tech/1012846/meta-business-terms-scrape-news-publishers" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="jev-成为-vercel-史上采用最快的-ai-模型" tabindex="-1">Jev 成为 Vercel 史上采用最快的 AI 模型 <a class="header-anchor" href="#jev-成为-vercel-史上采用最快的-ai-模型" aria-label="Permalink to &quot;Jev 成为 Vercel 史上采用最快的 AI 模型&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-10-16">2026-10-16</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/3fef669295c6.jpg" alt="配图"></p><p>TechCrunch 援引 Vercel AI gateway（类似 OpenRouter 的统一 API 服务）数据称，Jev 是 Vercel 平台上采用速度最快的 AI 模型。对读者：网关侧的真实调用数据是观察模型热度的重要信号，选型时可参考这类第三方流量指标而非只看榜单。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/10/16/jev-is-vercels-fastest-adopted-ai-model-ever/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="stack-overflow-for-agents-借-chatgpt-插件注册量翻三倍" tabindex="-1">Stack Overflow for Agents 借 ChatGPT 插件注册量翻三倍 <a class="header-anchor" href="#stack-overflow-for-agents-借-chatgpt-插件注册量翻三倍" aria-label="Permalink to &quot;Stack Overflow for Agents 借 ChatGPT 插件注册量翻三倍&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-10-16">2026-10-16</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/861622e803cc.png" alt="配图"></p><p>两名工程师用 Codex 数周内做出 Stack Overflow for Agents，其 ChatGPT 插件带动 agent 创建量最高增长约 10 倍，注册量翻三倍。对读者：小团队做 Agent 产品时，把分发挂在已有 AI 入口上，往往比自建流量更划算，值得纳入增长方案。</p><p class="news-entry-source"><a href="https://openai.com/index/stack-overflow-chatgpt-plugin" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="chatgpt-现在能读取你的-chrome-标签页" tabindex="-1">ChatGPT 现在能读取你的 Chrome 标签页 <a class="header-anchor" href="#chatgpt-现在能读取你的-chrome-标签页" aria-label="Permalink to &quot;ChatGPT 现在能读取你的 Chrome 标签页&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-10-16">2026-10-16</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/d5466612d892.png" alt="配图"></p><p>ChatGPT 的 Chrome 扩展升级，安装后可在网页版或桌面端调用你已打开的标签页内容，并支持侧边栏在当前页面直接对话，官方演示了对比多个商品标签页的用法。对读者：这类能力便利但涉及浏览数据边界，企业环境应先确认扩展权限与数据留存策略再放开。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/1012510/openai-chatgpt-google-chrome-tabs" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="openai-向学术实验室开放-gpt-rosalind" tabindex="-1">OpenAI 向学术实验室开放 GPT-Rosalind <a class="header-anchor" href="#openai-向学术实验室开放-gpt-rosalind" aria-label="Permalink to &quot;OpenAI 向学术实验室开放 GPT-Rosalind&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-10-16">2026-10-16</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/a2b2c5a86e79.png" alt="配图"></p><p>OpenAI 推出 Rosalind Academic Plan，符合条件的学术实验室可获赞助访问 GPT-Rosalind 及配套工具，用于推进生命科学研究。对读者：高校与科研团队可关注申请门槛，把模型能力接入既有实验流程，但需提前规划数据合规与成果归属。</p><p class="news-entry-source"><a href="https://openai.com/index/introducing-the-rosalind-academic-plan" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="claude-code-团队如何做代码评审" tabindex="-1">Claude Code 团队如何做代码评审 <a class="header-anchor" href="#claude-code-团队如何做代码评审" aria-label="Permalink to &quot;Claude Code 团队如何做代码评审&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Claude Blog</span><time datetime="2026-10-16">2026-10-16</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/9ef400763b81.png" alt="配图"></p><p>Claude Code 团队分享其评审流程：先让 Claude 自查，再按风险分级决定人工审批比例，目标是在不增加回滚与事故的前提下压缩人工评审时间，并给出可照搬的清单。对读者：Agent 产出代码量激增时，按风险分层而非全量人工评审，是更可持续的工程做法。</p><p class="news-entry-source"><a href="https://claude.dev/blog/solving-code-review-at-anthropic/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="meta-发布-muse-spark-open-816b-开源权重-moe-1m-上下文" tabindex="-1">Meta 发布 Muse Spark Open：816B 开源权重 MoE，1M 上下文 <a class="header-anchor" href="#meta-发布-muse-spark-open-816b-开源权重-moe-1m-上下文" aria-label="Permalink to &quot;Meta 发布 Muse Spark Open：816B 开源权重 MoE，1M 上下文&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-10-16">2026-10-16</time></p><p>Meta 推出 Muse Spark Open，816B 参数 MoE、激活 42B、支持 1M token 上下文，在 MCP-Atlas 上领先开源模型，可跑在两台 M5 Ultra Mac Studio 上。同期 AWS 已将其上架 SageMaker JumpStart。对读者：若在评估自托管编码模型，可先测其长上下文与 MCP 工具调用表现，再决定是否替换现有方案。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/10/15/meta-muse-spark-open-816b-open-weight-model/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="liquid-ai-发布-d1-ultra-单次前向输出校准概率的多模态决策模型" tabindex="-1">Liquid AI 发布 d1-ultra：单次前向输出校准概率的多模态决策模型 <a class="header-anchor" href="#liquid-ai-发布-d1-ultra-单次前向输出校准概率的多模态决策模型" aria-label="Permalink to &quot;Liquid AI 发布 d1-ultra：单次前向输出校准概率的多模态决策模型&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-10-16">2026-10-16</time></p><p>Liquid AI 发布 d1-ultra，支持文本与图像输入，一次前向即可返回校准概率，在 Artificial Analysis Decision Index 上得 65 分，输入价格约每百万 token 0.042 美元。对读者：做风控、路由等需要概率输出的场景，可把它当作低成本基线，但需自行验证校准度是否匹配业务阈值。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/10/15/liquid-ai-d1-ultra-decision-model/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="nvidia-发布-nemotron-3-5-super-vl-120b-开源多模态-agent-模型" tabindex="-1">NVIDIA 发布 Nemotron 3.5 Super VL：120B 开源多模态 Agent 模型 <a class="header-anchor" href="#nvidia-发布-nemotron-3-5-super-vl-120b-开源多模态-agent-模型" aria-label="Permalink to &quot;NVIDIA 发布 Nemotron 3.5 Super VL：120B 开源多模态 Agent 模型&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-10-16">2026-10-16</time></p><p>NVIDIA 推出 Nemotron 3.5 Super VL，120B 参数多模态 MoE、激活 12B、1M token 上下文，NVFP4 权重可单台 DGX Spark 运行，另附两个 Bolt 边缘模型。对读者：想在边缘或单机部署多模态 Agent 的团队，可优先评估其显存占用与工具调用链路。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/10/15/nvidia-nemotron-3-5-super-vl-release/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="claude-独立设计出更高效的量子电路" tabindex="-1">Claude 独立设计出更高效的量子电路 <a class="header-anchor" href="#claude-独立设计出更高效的量子电路" aria-label="Permalink to &quot;Claude 独立设计出更高效的量子电路&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Anthropic Research</span><time datetime="2026-10-16">2026-10-16</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/b7cbe3f5f4e8.webp" alt="配图"></p><p>Anthropic 给 Claude 八条来自化学、优化、物理等领域的自然语言电路规格，Claude 基本自主完成设计，部分结果比已发表最优版本提升一个数量级。对读者：这说明模型在结构化科学设计任务上已可作初筛工具，但落地前仍需领域专家复核与仿真验证。</p><p class="news-entry-source"><a href="https://www.anthropic.com/research/designing-efficient-quantum-circuits" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="reflection-的-beam-限时免费上线-ollama" tabindex="-1">Reflection 的 Beam 限时免费上线 Ollama <a class="header-anchor" href="#reflection-的-beam-限时免费上线-ollama" aria-label="Permalink to &quot;Reflection 的 Beam 限时免费上线 Ollama&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Ollama Blog</span><time datetime="2026-10-16">2026-10-16</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/2a07483d0c38.png" alt="配图"></p><p>Reflection 首个开源权重模型 Beam 已在 Ollama 上线并限时免费，面向软件工程、推理与长时程 Agent 任务，可通过 Ollama Cloud 访问；Hugging Face 侧标注为 501B 开源模型。对读者：想低成本试跑 Agent 编码模型的团队，可趁免费期做一轮真实任务压测再决定是否自托管。</p><p class="news-entry-source"><a href="https://ollama.com/blog/reflection-beam" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="cloudflare-为已验证机器人引入持续问责机制" tabindex="-1">Cloudflare 为已验证机器人引入持续问责机制 <a class="header-anchor" href="#cloudflare-为已验证机器人引入持续问责机制" aria-label="Permalink to &quot;Cloudflare 为已验证机器人引入持续问责机制&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Cloudflare Blog</span><time datetime="2026-10-16">2026-10-16</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/1e766fc3f3cf.webp" alt="配图"></p><p>Cloudflare 推出新系统，持续评估已验证机器人是否遵守 robots.txt、HTTP 429 等站点偏好，因为身份认证本身并不保证行为负责。对读者：站点运营方可借此把「白名单」从一次性认证升级为持续合规，Agent 抓取方则需确保自身行为可被验证。</p><p class="news-entry-source"><a href="https://blog.cloudflare.com/verified-bots-accountability/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p class="news-empty-day" data-i18n="news.emptyDay">（本日无新条目）</p></div>',8)])])}const u=a(s,[["render",o]]);export{m as __pageData,u as default};
